/* DWARF original prototype: LPITEM GetItem(CHARACTER * this, BYTE bCell) */

LPITEM __thiscall CHARACTER::GetItem(CHARACTER *this,BYTE bCell)

{
  LPITEM pCVar1;
  
  if (bCell < 0x6d) {
    pCVar1 = (this->m_pointsInstant).pItems[bCell];
  }
  else {
    _sys_err("GetItem",0xd4,"CHARACTER::GetItem: invalid item cell %d",(uint)bCell);
    pCVar1 = (LPITEM)0x0;
  }
  return pCVar1;
}
